package br.edu.cesar.treinoconecta.treinoconectacore.infraestrutura.core.desafio;
import java.math.BigDecimal;import java.time.OffsetDateTime;import java.util.Objects;import org.jspecify.annotations.Nullable;import jakarta.persistence.*;
@Entity @Table(name="DAF_AVALIACAO_DESAFIO",uniqueConstraints=@UniqueConstraint(name="UK_DAF_REFERENCIA",columnNames={"DAF_ID","DES_ID","ALU_ID"}))
public class AvaliacaoDesafioJpa {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="DAF_ID") private @Nullable Long identificador;@Column(name="DES_ID",nullable=false)private Long desafio;@Column(name="ALU_ID",nullable=false)private Long aluno;@Column(name="PRF_ID",nullable=false)private Long profissional;@Column(name="DAF_TIPO",nullable=false,length=16)private String tipo;@Column(name="DAF_PESO",nullable=false,precision=6,scale=2)private BigDecimal peso;@Column(name="DAF_CINTURA",nullable=false,precision=6,scale=2)private BigDecimal cintura;@Column(name="DAF_GORDURA",nullable=false,precision=5,scale=2)private BigDecimal gordura;@Column(name="DAF_REGISTRO",nullable=false)private OffsetDateTime registro;
 protected AvaliacaoDesafioJpa(){}
 public AvaliacaoDesafioJpa(Long desafio,Long aluno,Long profissional,String tipo,BigDecimal peso,BigDecimal cintura,BigDecimal gordura,OffsetDateTime registro){this.desafio=Objects.requireNonNull(desafio);this.aluno=Objects.requireNonNull(aluno);this.profissional=Objects.requireNonNull(profissional);this.tipo=Objects.requireNonNull(tipo);this.peso=Objects.requireNonNull(peso);this.cintura=Objects.requireNonNull(cintura);this.gordura=Objects.requireNonNull(gordura);this.registro=Objects.requireNonNull(registro);}
 public Long getIdentificador(){return Objects.requireNonNull(identificador);}public Long getDesafio(){return desafio;}public Long getAluno(){return aluno;}public Long getProfissional(){return profissional;}public String getTipo(){return tipo;}public BigDecimal getPeso(){return peso;}public BigDecimal getCintura(){return cintura;}public BigDecimal getGordura(){return gordura;}public OffsetDateTime getRegistro(){return registro;}
 public void atualizar(BigDecimal peso,BigDecimal cintura,BigDecimal gordura){this.peso=Objects.requireNonNull(peso);this.cintura=Objects.requireNonNull(cintura);this.gordura=Objects.requireNonNull(gordura);}
}
